refentry.refsect1:
  &reftitle.examples;

   Exemplo de Yac::add


<?php
$yac = new Yac();

var_dump($yac->add("foo", "bar"));          // bool(true)
var_dump($yac->add("foo", "baz"));          // bool(false): "foo" já existe
?>




   Adicionando uma entrada com TTL


<?php
$yac = new Yac();

// TTL em segundos; 0 (o padrão) significa que a entrada nunca expira
$yac->add("short-lived", "value", 5);
sleep(6);
var_dump($yac->get("short-lived"));        // bool(false): expirada
?>




   Adicionando várias entradas de uma vez


<?php
$yac = new Yac();

// armazena vários pares chave => valor em uma chamada, com um TTL
$yac->add(array("a" => 1, "b" => 2), 60);
?>
